function getMicrosoftSentinelTranslation(key, lang) {
    return (microsoftsentinelTranslations[lang] && microsoftsentinelTranslations[lang][key]) ||
           (microsoftsentinelTranslations.en && microsoftsentinelTranslations.en[key]) || null;
}

function applyMicrosoftSentinelTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.microsoft-sentinel.") || key.startsWith("review.common."))) {
            const translation = getMicrosoftSentinelTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyMicrosoftSentinelTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyMicrosoftSentinelTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyMicrosoftSentinelTranslations(window.i18n?.getCurrentLanguage() || "en");
}
